index cfc5590..bb29a14 100644
--- a/include/tvm/ffi/container/container_details.h
+++ b/include/tvm/ffi/container/container_details.h
@@ -199,6 +199,16 @@ class IterAdapter {

   IterAdapter operator-(difference_type offset) const { return IterAdapter(iter_ - offset); }

+  IterAdapter& operator+=(difference_type offset) {
+    iter_ += offset;
+    return *this;
+  }
+
+  IterAdapter& operator-=(difference_type offset) {
+    iter_ -= offset;
+    return *this;
+  }
